char *compressString(char *S) {
  int n = strlen(S);
  char *res = (char *)malloc(n * 2 + 16);
  int p = 0;
  for (int i = 0; i < n;) {
    int j = i;
    while (j < n && S[j] == S[i]) j++;
    p += sprintf(res + p, "%c%d", S[i], j - i);
    i = j;
  }
  res[p] = '\0';
  if (p >= n) {
    free(res);
    char *orig = (char *)malloc(n + 1);
    memcpy(orig, S, n + 1);
    return orig;
  }
  return res;
}

class Solution {
public:
  string compressString(string S) {
    string res;
    int n = S.size();
    for (int i = 0; i < n;) {
      int j = i;
      while (j < n && S[j] == S[i]) j++;
      res += S[i];
      res += to_string(j - i);
      i = j;
    }
    return res.size() < S.size() ? res : S;
  }
};

