class Solution {
  public String compressString(String S) {
    StringBuilder sb = new StringBuilder();
    int n = S.length();
    for (int i = 0; i < n;) {
      int j = i;
      while (j < n && S.charAt(j) == S.charAt(i)) j++;
      sb.append(S.charAt(i)).append(j - i);
      i = j;
    }
    String res = sb.toString();
    return res.length() < S.length() ? res : S;
  }
}

class Solution:
    def compressString(self, S: str) -> str:
        res = []
        n = len(S)
        i = 0
        while i < n:
            j = i
            while j < n and S[j] == S[i]:
                j += 1
            res.append(S[i] + str(j - i))
            i = j
        out = "".join(res)
        return out if len(out) < len(S) else S

impl Solution {
  pub fn compress_string(s: String) -> String {
    let b = s.as_bytes();
    let n = b.len();
    let mut res = String::new();
    let mut i = 0;
    while i < n {
      let mut j = i;
      while j < n && b[j] == b[i] {
        j += 1;
      }
      res.push(b[i] as char);
      res.push_str(&(j - i).to_string());
      i = j;
    }
    if res.len() < s.len() {
      res
    } else {
      s
    }
  }
}

const compressString = (S: string): string => {
  let res = '';
  const n = S.length;
  let i = 0;
  while (i < n) {
    let j = i;
    while (j < n && S[j] === S[i]) j++;
    res += S[i] + String(j - i);
    i = j;
  }
  return res.length < S.length ? res : S;
};
